namespace VrcSetup.Core;

public static class PackagePresence
{
    // Generated by their owning tools, never downloadable preset dependencies.
    // Use known identities, not a broad suffix rule that could hide real packages.
    public static bool IsGenerated(string id) => id.Equals("com.vrcfury.temp", StringComparison.OrdinalIgnoreCase)
        || id.Equals("dev.dor.avatarsetup.temp", StringComparison.OrdinalIgnoreCase);

    public static Dictionary<string, string> Selection(IReadOnlyDictionary<string, string> source) =>
        source.Where(x => !IsGenerated(x.Key)).ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase);

    public static IEnumerable<string> Ids(ProjectSnapshot project) => project.Packages.Keys.Concat(project.LockedPackages.Keys)
        .Concat(project.InstalledVersions.Keys.Where(x => !x.StartsWith("com.unity.", StringComparison.OrdinalIgnoreCase)))
        .Where(x => !IsGenerated(x)).Distinct(StringComparer.OrdinalIgnoreCase);

    public static bool Contains(ProjectSnapshot project, string id) => !IsGenerated(id) &&
        (project.Packages.ContainsKey(id) || project.LockedPackages.ContainsKey(id) || project.InstalledVersions.ContainsKey(id));

    public static bool Matches(PackageChange change, ProjectSnapshot project)
    {
        var installed = project.InstalledVersions.GetValueOrDefault(change.Id);
        if (installed is null || !Contains(project, change.Id)) return false;
        if (project.LockedPackages.TryGetValue(change.Id, out var locked) && locked != installed) return false;
        if (installed == change.ResolvedVersion) return true;
        // VPM owns dependency/version resolution. A latest lookup is only a UI
        // suggestion, never a second solver or a reason to force a downgrade.
        if (change.RequestedVersion != "latest" || project.LockedPackages.GetValueOrDefault(change.Id) != installed) return false;
        try { _ = new SemanticVersion(installed); return true; }
        catch (ArgumentException) { return false; }
    }
}
